package com.bananalab.lite;
/** Independent backdrop controls preserve cast, designs and executable sequence. */
final class SceneSettings{
 static CreatorSession.Result apply(String input,SceneDraft base)throws Exception{String q=CreationRequest.normalize(input);boolean lighting=q.matches("(?:pone |hace |cambia |deja )?(?:el fondo |la escena |la luz |el ambiente )?(?:de dia|de noche|mas claro|mas oscuro|luz calida|iluminacion calida|luz de dia|luz de noche)"),fog=q.matches("(?:agrega |pone |quita |saca |deja |sin |con )?(?:poca |mucha )?niebla"),tree=q.matches("(?:agrega|pone|quita|saca) (?:un |el )?arbol(?: en el fondo| al fondo| del fondo)?"),place=q.matches("(?:cambia|pone) el fondo (?:a|en) (?:el |la |un |una )?(bosque|parque|playa|ciudad|montana|pasillo)");if(!lighting&&!fog&&!tree&&!place)return null;if(base==null)return CreatorSession.say("Primero creá una escena para ajustar su ambiente.");SceneDraft d=base.copy();if(lighting)d.lighting=q.contains("calida")?"warm":q.contains("noche")||q.contains("oscuro")?"night":"day";if(fog)d.fog=q.matches("(?:quita|saca|sin).*niebla")?0:q.contains("mucha")?.4f:q.contains("poca")?.1f:.23f;if(tree)d.sceneryTree=q.startsWith("agrega")||q.startsWith("pone");if(place)d.setting=q.substring(q.lastIndexOf(' ')+1);return new CreatorSession.Result(true,"Actualicé el ambiente conservando personajes, diseños y acciones.",d);}
}
